/**
 * The radial bar extension type. Importing this module
 * registers `radialBar`: one ring per `x` category from the innermost out,
 * each an arc from `startAngle` whose sweep is its value over `max` of the
 * `endAngle` range (default 270 degrees), with a faint full track behind it.
 */
export function drawRadialBar(ctx: object): object;
export default drawRadialBar;
